import itertools, random
MOD=998244353
def fast(n,conds):
 by=[[n+1]*(n+1) for _ in range(n)]
 for L,R,X in conds: by[X][L]=min(by[X][L],R)
 for x in range(n):
  cur=n+1
  for l in range(n-1,-1,-1): cur=min(cur,by[x][l]);by[x][l]=cur
 C=[[0]*(n+1) for _ in range(n+1)]
 for i in range(n+1):
  C[i][0]=C[i][i]=1
  for j in range(1,i):C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
 dp=[[0]*n for _ in range(n)]
 for z in range(1,n+1):
  for l in range(n-z+1):
   r=l+z-1
   dp[l][r]=sum((dp[l][p-1] if p>l else 1)*(dp[p+1][r] if p<r else 1)*C[z-1][p-l] for p in range(l,r+1) if r<by[p][l])%MOD
 return dp[0][n-1]
def brute(n,c):
 ans=0
 for P in itertools.permutations(range(n)):
  if all(max(P[L:R+1])!=P[X] for L,R,X in c):ans+=1
 return ans
