import sys
MOD=998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    factors = []
    primes = set()
    for value in values:
        x = value
        f = {}
        divisor = 2
        while divisor * divisor <= x:
            if x % divisor == 0:
                exponent = 0
                while x % divisor == 0:
                    x //= divisor
                    exponent += 1
                f[divisor] = exponent
                primes.add(divisor)
            divisor += 1
        if x > 1:
            f[x] = f.get(x, 0) + 1
            primes.add(x)
        factors.append(f)

    answer = 1
    for prime in primes:
        exponents = [f.get(prime, 0) for f in factors]
        total = sum(exponents)
        powers = [1] * (total + 1)
        for k in range(1, total + 1):
            powers[k] = powers[k - 1] * prime % MOD

        # h is the current valuation after subtracting the minimum so far.
        # Each DP value includes the product of the normalized valuations
        # of all nodes processed so far.
        dp = {0: 1}
        for edge, exponent in enumerate(exponents):
            next_dp = {}
            base = pow(prime, edge + 1, MOD)
            shift_powers = [1] * (exponent + 1)
            for k in range(1, exponent + 1):
                shift_powers[k] = shift_powers[k - 1] * base % MOD

            choices = (exponent, -exponent) if exponent else (0,)
            for height, ways in dp.items():
                for delta in choices:
                    new_height_raw = height - delta
                    if new_height_raw >= 0:
                        new_height = new_height_raw
                        multiplier = powers[new_height]
                    else:
                        shift = -new_height_raw
                        new_height = 0
                        # The minimum drops by shift, raising all previous
                        # (edge + 1) normalized valuations by that amount.
                        multiplier = shift_powers[shift]
                    next_dp[new_height] = (
                        next_dp.get(new_height, 0) + ways * multiplier
                    ) % MOD
            dp = next_dp

        answer = answer * sum(dp.values()) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

