import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    values = data[1:]
    mx = max(values, default=1)
    spf = list(range(mx + 1))
    for i in range(2, int(mx ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i
    nim_sum = 0
    for x in values:
        factors = 0
        while x > 1:
            factors += 1
            x //= spf[x]
        nim_sum ^= factors
    print('Anna' if nim_sum else 'Bruno')

