import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []

    for i in range(n):
        a, p, b, q = data[2 + 4*i: 6 + 4*i]
        g = math.gcd(a, b)

        if p * (b // g) <= q * (a // g):
            # Replacing a/g units of T by b/g units of S never increases cost.
            # Thus an optimum exists with fewer than a/g units of T.
            limit = a // g

            def cost(k, a=a, p=p, b=b, q=q, limit=limit):
                best = 10**30
                for t in range(limit):
                    rem = k - b * t
                    s = 0 if rem <= 0 else (rem + a - 1) // a
                    value = t * q + s * p
                    if value < best:
                        best = value
                return best
        else:
            # Symmetrically, an optimum exists with fewer than b/g units of S.
            limit = b // g

            def cost(k, a=a, p=p, b=b, q=q, limit=limit):
                best = 10**30
                for s in range(limit):
                    rem = k - a * s
                    t = 0 if rem <= 0 else (rem + b - 1) // b
                    value = s * p + t * q
                    if value < best:
                        best = value
                return best

        processes.append(cost)

    def feasible(target):
        total = 0
        for cost in processes:
            total += cost(target)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

