class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Pascal's triangle: C[i][j] counts ways to choose j positions from i.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x has c set bits and x > 1, its first operation gives c;
        # hence it is reducible in 1 + steps(c) operations.
        good = []
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            if steps + 1 <= k:
                good.append(c)

        # Count numbers smaller than s, grouped by their number of set bits.
        ans = 0
        ones_before = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                for c in good:
                    needed = c - ones_before
                    if 0 <= needed <= remaining:
                        ans += comb[remaining][needed]
                ones_before += 1

        return ans % MOD

