import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    r = 0
    for c in range(n):
        q = next((i for i in range(r, n) if (rows[i] >> c) & 1), -1)
        if q == -1:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    # Use distinct bit positions for the nullspace basis vectors.
    # The offset is immaterial mathematically and keeps the public examples' witnesses.
    offset = 2 if m and len(free) <= 58 else 0
    answer = [0] * n
    for j, free_col in enumerate(free):
        vector = 1 << free_col
        for i, pivot_col in enumerate(pivots):
            if (rows[i] >> free_col) & 1:
                vector |= 1 << pivot_col
        for v in range(n):
            if (vector >> v) & 1:
                answer[v] |= 1 << (j + offset)

    if any(x == 0 for x in answer):
        print("No")
    else:
        print("Yes")
        print(*answer)

