    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(data[3:3+M])
    # Small cases can be handled by direct enumeration.
    if N <= 10 and K ** N <= 2_000_000:
        from itertools import product
        ans = 0
        for a in product(range(1, K+1), repeat=N):
            seen = set()
            # Enumerate all length-M subsequences.
            def rec(i, j, word):
                if j == M:
                    seen.add(tuple(word))
                    return
                if N-i < M-j:
                    return
                for p in range(i, N-(M-j)+1):
                    word.append(a[p])
                    rec(p+1, j+1, word)
                    word.pop()
            rec(0, 0, [])
            if len(seen) == K**M-1 and X not in seen:
                ans += 1
        print(ans % 998244353)
