from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # Clockwise order in screen coordinates: SE, SW, NW, NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # straight[d][q][i][j] is the number of cells after (i,j)
        # in direction d, starting with expected value (2 if q=0, else 0).
        straight = []
        for dr, dc in dirs:
            a = [[[0] * m for _ in range(n)] for _ in range(2)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                for j in range(m):
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m:
                        for q, value in enumerate((2, 0)):
                            if grid[ni][nj] == value:
                                a[q][i][j] = 1 + a[1 - q][ni][nj]
            straight.append(a)

        answer = 0
        for d, (dr, dc) in enumerate(dirs):
            tr, tc = dirs[(d + 1) % 4]
            # best[q][i][j]: longest sequence including (i,j), whose
            # value is the expected value for q, allowing one clockwise turn.
            best = [[[0] * m for _ in range(n)] for _ in range(2)]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                for j in range(m):
                    for q, value in enumerate((2, 0)):
                        if grid[i][j] != value:
                            continue
                        other = 1 - q
                        next_value = (0 if value == 2 else 2)
                        length = 0

                        ni, nj = i + dr, j + dc
                        if (0 <= ni < n and 0 <= nj < m
                                and grid[ni][nj] == next_value):
                            length = best[other][ni][nj]

                        ni, nj = i + tr, j + tc
                        if (0 <= ni < n and 0 <= nj < m
                                and grid[ni][nj] == next_value):
                            length = max(length, straight[(d + 1) % 4][other][i][j])

                        best[q][i][j] = 1 + length

            for i in range(n):
                for j in range(m):
                    if grid[i][j] != 1:
                        continue
                    answer = max(answer, 1)
                    ni, nj = i + dr, j + dc
                    if (0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 2):
                        answer = max(answer, 1 + best[0][ni][nj])

        return answer

