class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        coeff = [0] * m
        for i in range(m):
            if i == n - 1 - i:
                coeff[i] = powers[i]
            else:
                coeff[i] = (powers[i] + powers[n - 1 - i]) % k
        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            for d in range(10):
                s = d * c % k
                r = suffix[i + 1]
                mask |= r if s == 0 else ((r << s) | (r >> (k - s))) & full
            suffix[i] = mask
        digits = [0] * n
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-(rem + d * c)) % k
                if (suffix[i + 1] >> need) & 1:
                    digits[i] = digits[n - 1 - i] = d
                    rem = (rem + d * c) % k
                    break
        return ''.join(map(str, digits))

