 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); pre=[0]*(n+1)
  for i,x in enumerate(nums): pre[i+1]=pre[i]+x
  ng=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   ng[i]=st[-1] if st else n; st.append(i)
  U=[ng[:]]; C=[[nums[i]*(ng[i]-i)-(pre[ng[i]]-pre[i]) for i in range(n)]]
  while (1<<len(U))<=n:
   pu,pc=U[-1],C[-1]; uu=[n]*n; cc=[0]*n
   for i in range(n):
    m=pu[i]; uu[i]=pu[m] if m<n else n; cc[i]=pc[i]+(pc[m] if m<n else 0)
   U.append(uu); C.append(cc)
  def cost(l,r):
   lim=r+1; pos=l; val=0
   for j in range(len(U)-1,-1,-1):
    if pos==n: break
    q=U[j][pos]
    if q<=lim and q>pos: val+=C[j][pos]; pos=q
   if pos<lim: val+=nums[pos]*(lim-pos)-(pre[lim]-pre[pos])
   return val
  ans=0
  for l in range(n):
   lo=l-1; hi=n
   while hi-lo>1:
    m=(lo+hi)//2
    if cost(l,m)<=k: lo=m
    else: hi=m
   ans+=lo-l+1
  return ans
