class Solution:
    def makeStringGood(self, s: str) -> int:
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        # For a fixed target frequency k, carry is the number of characters
        # changed from the previous letter. At each letter, choose a final
        # frequency of either 0 or k.
        answer = len(s)
        for k in range(1, max(freq) + 1):
            dp = [0]  # cost by incoming carry; initially only carry 0 is possible
            for i in range(26):
                f = freq[i]
                ndp = [10**9] * (k + 1)
                for incoming, base in enumerate(dp):
                    if base == 10**9:
                        continue
                    available = f + incoming
                    for outgoing in range(k + 1):
                        if i == 25 and outgoing:
                            continue
                        # Choose final count 0 or k. Any mismatch is handled
                        # by insertions or deletions; outgoing changes cost one.
                        cost0 = outgoing + abs(available - outgoing)
                        ndp[outgoing] = min(ndp[outgoing], base + cost0)
                        costk = outgoing + abs(k + outgoing - available)
                        ndp[outgoing] = min(ndp[outgoing], base + costk)
                dp = ndp
            answer = min(answer, dp[0])
        return answer

