from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first = p.find('*')
        second = p.find('*', first + 1)
        parts = (p[:first], p[first + 1:second], p[second + 1:])

        def occurrences(pattern):
            m = len(pattern)
            if m == 0:
                return list(range(n + 1))

            # Prefix-function for KMP.
            prefix = [0] * m
            matched = 0
            for i in range(1, m):
                while matched and pattern[i] != pattern[matched]:
                    matched = prefix[matched - 1]
                if pattern[i] == pattern[matched]:
                    matched += 1
                prefix[i] = matched

            result = []
            matched = 0
            for i, ch in enumerate(s):
                while matched and ch != pattern[matched]:
                    matched = prefix[matched - 1]
                if ch == pattern[matched]:
                    matched += 1
                if matched == m:
                    result.append(i - m + 1)
                    matched = prefix[matched - 1]
            return result

        a, b, c = parts
        occ_a, occ_b, occ_c = (occurrences(part) for part in parts)
        len_a, len_b, len_c = len(a), len(b), len(c)
        answer = n + 1

        for start_b in occ_b:
            # Latest A ending before B, and earliest C starting after B.
            idx_a = bisect_right(occ_a, start_b - len_a) - 1
            idx_c = bisect_left(occ_c, start_b + len_b)
            if idx_a >= 0 and idx_c < len(occ_c):
                length = occ_c[idx_c] + len_c - occ_a[idx_a]
                answer = min(answer, length)

        return answer if answer <= n else -1

