from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        i = p.find('*')
        j = p.find('*', i + 1)
        parts = (p[:i], p[i+1:j], p[j+1:])

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))
            # KMP prefix function
            pi = [0] * m
            k = 0
            for x in range(1, m):
                while k and t[x] != t[k]:
                    k = pi[k-1]
                if t[x] == t[k]:
                    k += 1
                pi[x] = k
            out = []
            k = 0
            for x, ch in enumerate(s):
                while k and ch != t[k]:
                    k = pi[k-1]
                if ch == t[k]:
                    k += 1
                if k == m:
                    out.append(x-m+1)
                    k = pi[k-1]
            return out

        A, B, C = parts
        oa, ob, oc = (occurrences(x) for x in parts)
        best = n + 1
        la, lb, lc = len(A), len(B), len(C)
        for b in ob:
            ai = bisect_right(oa, b-la)-1
            ci = bisect_left(oc, b+lb)
            if ai >= 0 and ci < len(oc):
                length = oc[ci] + lc - oa[ai]
                if length < best:
                    best = length
        return best if best <= n else -1

