import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        queue = [start]
        component = []
        for v in queue:
            component.append(v)
            for w, z in adj[v]:
                expected = potential[v] ^ z
                if potential[w] == -1:
                    potential[w] = expected
                    queue.append(w)
                elif potential[w] != expected:
                    print(-1)
                    return

        ones = [0] * 31
        for v in component:
            value = potential[v]
            for bit in range(31):
                ones[bit] += (value >> bit) & 1
        root_value = 0
        size = len(component)
        for bit, count in enumerate(ones):
            if count > size - count:
                root_value |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ root_value

    print(*answer)

if __name__ == '__main__':
    main()

