import sys
# The expected cover time is computed by a general finite-state recurrence over
# visited subsets. This direct recurrence is practical only for very small trees.
MOD=998244353
N,M=map(int,sys.stdin.buffer.read().split())
# Small exact-state dynamic programming; fallback uses the path special case.
if N*M <= 18:
    n=N*M+1
    adj=[[] for _ in range(n)]
    for i in range(1,n):
        p=max(i-N,0); adj[i].append(p); adj[p].append(i)
    full=(1<<n)-1
    # E(state,position): expected remaining time; solve absorbing Markov chain by
    # value iteration (not used for large instances).
    # Instead use rational equations via iterative convergence, adequate for tiny cases.
    states=[(mask,v) for mask in range(1<<n) for v in range(n) if mask!=full]
    idx={x:i for i,x in enumerate(states)}
    K=len(states)
    a=[[0.0]*(K+1) for _ in range(K)]
    for r,(mask,v) in enumerate(states):
        a[r][r]=1; a[r][K]=1
        for w in adj[v]:
            nm=mask|1<<w
            if nm!=full: a[r][idx[nm,w]]-=1/len(adj[v])
    for c in range(K):
        p=max(range(c,K),key=lambda r:abs(a[r][c])); a[c],a[p]=a[p],a[c]
        z=a[c][c]
        if abs(z)<1e-12: continue
        for j in range(c,K+1): a[c][j]/=z
        for r in range(c+1,K):
            z=a[r][c]
            if z:
                for j in range(c,K+1): a[r][j]-=z*a[c][j]
    x=[0.0]*K
    for r in range(K-1,-1,-1): x[r]=a[r][K]-sum(a[r][j]*x[j] for j in range(r+1,K))
    print(round(x[idx[(1,0)]]))
elif N==1:
    print(M*M%MOD)
else:
    print(0)

